}

private wrapRateLimit<Req extends { meta?: { module_id?: string } }, Res>(
	rpcName: string,
	handler: (call: grpc.ServerUnaryCall<Req, Res>, callback: grpc.sendUnaryData<Res>) => void
) {
	if (!this.rateLimiter) return handler;
	return this.rateLimiter.wrapUnary(
		rpcName,
		(call: grpc.ServerUnaryCall<Req, Res>) => call.request?.meta?.module_id,
		handler
	);
}

