private createChannel(
	call: grpc.ServerUnaryCall<GrpcCreateChannelRequest, any>,
	callback: grpc.sendUnaryData<any>
) {
	const { guild_id, name, meta, ...rest } = call.request;
	if (!meta?.module_id)
		return callback(null, ResponseBuilder.unauthenticated("Missing module_id", meta?.trace_id));
	if (!meta?.trace_id)
		return callback(null, ResponseBuilder.validationError("trace_id", "Missing trace_id", meta?.trace_id));
