import cluster from "node:cluster";
import { createLogger } from "@kena/logger";

export const LogType = {
	MASTER: "MASTER",
	WORKER: "WORKER",
	DISCORD: "DISCORD",
	DB: "DB",
	REDIS: "REDIS",
	CLUSTER: "CLUSTER",
	SHARD: "SHARD",
	I18N: "I18N",
	GRPC: "GRPC",
	INFISICAL: "INFISICAL",
	GLITCHTIP: "GLITCHTIP",
	// Health / instrumentation: rss, heap, cpu, handler rates, dedup size,
	// buffer depths. Filtrable con `grep '"type":"HEALTH"'` para auditar
	// CPU/RAM sin ruido de eventos normales.
	HEALTH: "HEALTH"
} as const;

