import type { MessageResponseIPC } from "@kena/shared";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { RequestTracker } from "../../../../src/cluster/master/ipc/RequestTracker.js";

vi.mock("../../../../src/shared/Logger.js", () => ({
	logger: { info: vi.fn(), warn: vi.fn(), error: vi.fn(), debug: vi.fn() },
	LogType: { CLUSTER: "CLUSTER" }
}));

/**
 * Auditoría 2026-08-11 — `pendingRequests` sin `maxPending`.
 *
 * Sin techo, cada `trackRequest` entra sin condición: si el worker resuelve
 * más despacio de lo que entran peticiones, el Map crece indefinidamente
 * reteniendo closures + payload en vuelo. Estos tests fijan el contrato del
 * techo: por encima de `maxPending`, `trackRequest` rechaza de inmediato en
 * vez de encolar una entrada más.
 */
describe("RequestTracker — maxPending", () => {
	beforeEach(() => {
		vi.useFakeTimers();
	});

	afterEach(() => {
		vi.useRealTimers();
	});

	it("rejects new requests once the tracker is at capacity, without growing the map", async () => {
		const tracker = new RequestTracker(30000, 2);

		const first = tracker.trackRequest("trace-1");
		const second = tracker.trackRequest("trace-2");
		expect(tracker.getPendingCount()).toBe(2);

		await expect(tracker.trackRequest("trace-3")).rejects.toThrow(/at capacity/);
		expect(tracker.getPendingCount()).toBe(2);
		expect(tracker.getDroppedForCapacity()).toBe(1);

		// The two admitted requests are unaffected — capacity rejection only
		// applies to the request that overflowed.
		tracker.resolveRequest("trace-1", { success: true, request_id: "trace-1" } as MessageResponseIPC);
		tracker.resolveRequest("trace-2", { success: true, request_id: "trace-2" } as MessageResponseIPC);
		await expect(first).resolves.toMatchObject({ success: true });
		await expect(second).resolves.toMatchObject({ success: true });
	});

	it("admits a new request again once a pending one settles below the cap", async () => {
		const tracker = new RequestTracker(30000, 1);

		const first = tracker.trackRequest("trace-1");
		await expect(tracker.trackRequest("trace-2")).rejects.toThrow(/at capacity/);

		tracker.resolveRequest("trace-1", { success: true, request_id: "trace-1" } as MessageResponseIPC);
		await first;

		// Capacity freed up — this one should be admitted normally.
		const third = tracker.trackRequest("trace-3");
		expect(tracker.getPendingCount()).toBe(1);
		tracker.resolveRequest("trace-3", { success: true, request_id: "trace-3" } as MessageResponseIPC);
		await expect(third).resolves.toMatchObject({ success: true });
	});

	it("a superseding request (trace_id collision) does not count against capacity", async () => {
		const tracker = new RequestTracker(30000, 1);

		const first = tracker.trackRequest("trace-1");
		// Re-tracking the same id evicts the prior entry first, so it must
		// not be treated as growing past the cap.
		const second = tracker.trackRequest("trace-1");
		expect(tracker.getPendingCount()).toBe(1);

		await expect(first).rejects.toThrow(/superseded/);
		tracker.resolveRequest("trace-1", { success: true, request_id: "trace-1" } as MessageResponseIPC);
		await expect(second).resolves.toMatchObject({ success: true });
	});

	it("defaults to a positive cap when none is provided", () => {
		const tracker = new RequestTracker();
		expect(tracker.getDroppedForCapacity()).toBe(0);
		expect(tracker.getPendingCount()).toBe(0);
	});
});

