1	import { LogType, logger } from "../../../shared/Logger.js";
2	import type { MessageResponseIPC } from "../../../shared/types/cluster/message.js";
3	
4	interface PendingRequest {
5		resolve: (value: MessageResponseIPC) => void;
6		reject: (error: Error) => void;
7		timeout: NodeJS.Timeout;
8		timestamp: number;
9	}
10	
11	/**
12	 * Todos los trackers vivos del proceso.
13	 *
14	 * Existe para poder MEDIR: hay un tracker por servicio gRPC (diez), cada uno con
15	 * su `pendingRequests` privado, y hasta ahora `getPendingCount()` no lo llamaba
16	 * NADIE — la profundidad de la cola de peticiones en vuelo, que es la señal que
17	 * habría delatado la saturación del core antes de que un usuario dijera «no
18	 * funciona», se calculaba y se tiraba.
19	 *
20	 * Un registro aquí evita tener que abrir un getter público en cada uno de los
21	 * diez servicios, y hace que un servicio nuevo entre en la medición sin que nadie
22	 * se acuerde de añadirlo.
23	 */
24	const liveTrackers = new Set<RequestTracker>();
25	
26	/** Peticiones en vuelo AHORA MISMO, sumando todos los servicios. */
27	export function pendingRequestsSnapshot(): {
28		total: number;
29		trackers: number;
30		max: number;
31		droppedForCapacity: number;
32	} {
33		let total = 0;
34		let max = 0;
35		let droppedForCapacity = 0;
36		for (const tracker of liveTrackers) {
37			const pending = tracker.getPendingCount();
38			total += pending;
39			if (pending > max) max = pending;
40			droppedForCapacity += tracker.getDroppedForCapacity();
41		}
42		return { total, trackers: liveTrackers.size, max, droppedForCapacity };
43	}
44	
45	export class RequestTracker {
46		private readonly pendingRequests = new Map<string, PendingRequest>();
47		/**
48		 * Audit 1.6: a small ring of late-arriving success responses for
49		 * requests that already timed out. We keep them around for a brief
50		 * window so the caller (InteractionGrpcService) can convert a
51		 * tracker-induced DEFER_TIMEOUT into a real success when the worker's
52		 * POST actually completed before Discord rejected anything.
53		 */
54		private readonly lateSuccesses = new Map<string, MessageResponseIPC>();
55		/**
56		 * Bounded so the ring can't grow under a sustained stream of late
57		 * successes. 256 is a comfortable upper bound for the rate at which
58		 * a worker might legitimately be late (we keep the most recent 256).
59		 */
60		private static readonly LATE_SUCCESS_MAX = 256;
61		/**
62		 * Auditoría 2026-08-11 (RAM sin techo, agujero #1): `pendingRequests` no
63		 * tenía tope. Cada entrada retiene, vía closure, la promesa suspendida del
64		 * llamante — que a su vez retiene `call.request` completo, hasta 16 MiB
65		 * por `grpc.max_receive_message_length` — mientras espera al worker. Si
66		 * las peticiones entran más rápido de lo que el worker resuelve (el caso
67		 * real: automation-module a ~115 req/s contra un core que no daba abasto),
68		 * el Map crece sin que nada lo frene hasta agotar el heap.
69		 *
70		 * 2000 no está afinado a un experimento; es un techo de emergencia del
71		 * mismo orden que el resto de circuit breakers de este repo (el rate
72		 * limiter por defecto admite hasta 3000 peticiones de un módulo en 10s,
73		 * server.ts:81-82) — deja margen de sobra para picos legítimos y sigue
74		 * acotando la memoria a un múltiplo pequeño de ese techo en vez de a
75		 * "lo que aguante el proceso".
76		 */
77		private static readonly DEFAULT_MAX_PENDING = 2000;
78		private readonly defaultTimeout: number;
79		private readonly maxPending: number;
80		/** Peticiones rechazadas de entrada por estar el tracker a tope. */
81		private droppedForCapacity = 0;
82		private onSettle?: (request_id: string) => void;
83		private onLateSuccess?: (request_id: string, response: MessageResponseIPC) => void;
84	
85		constructor(defaultTimeout = 30000, maxPending = RequestTracker.DEFAULT_MAX_PENDING) {
86			// 30 seconds default
87			this.defaultTimeout = defaultTimeout;
88			this.maxPending = maxPending;
89			// Se apunta al registro para que la profundidad de la cola sea medible sin
90			// abrir un getter en cada servicio. Los trackers viven lo que el proceso, así
91			// que no hace falta darse de baja.
92			liveTrackers.add(this);
93		}
94	
95		/**
96		 * Register a callback fired whenever a request is fully settled (resolve,
97		 * reject, timeout, or supersede). Used by ClusterIPC to clear its
98		 * `pendingByCluster` rejector so a later cluster-exit doesn't try to
99		 * invoke a no-op `rejectRequest` and spam "Cannot reject unknown
100		 * request" warnings.
101		 */
102		setOnSettle(cb: (request_id: string) => void): void {
103			this.onSettle = cb;
104		}
105	
106		/**
107		 * Audit 1.6: register a callback fired when a success response arrives
108		 * for a request that has already timed out. The InteractionGrpcService
109		 * uses this to convert a tracker-induced DEFER_TIMEOUT into OK so the
110		 * SDK doesn't set deferFailed=true on a defer that actually succeeded.
111		 */
112		setOnLateSuccess(cb: (request_id: string, response: MessageResponseIPC) => void): void {
113			this.onLateSuccess = cb;
114		}
115	
116		/**
117		 * Track a request and return a promise that resolves when the response arrives
118		 */
119		trackRequest(request_id: string, timeoutMs?: number): Promise<MessageResponseIPC> {
120			// Collision: reject the previous holder immediately and clear its
121			// timer before installing the new one. Without this, the prior
122			// promise would leak until its 30s timer fires AND its expiry would
123			// delete the NEW entry — making the new caller's response land as
124			// "Received response for unknown request" and itself time out.
125			const prior = this.pendingRequests.get(request_id);
126			if (prior) {
127				clearTimeout(prior.timeout);
128				this.pendingRequests.delete(request_id);
129				prior.reject(new Error(`Request ${request_id} superseded by a new tracker entry (trace_id collision)`));
130				this.onSettle?.(request_id);
131				logger.warn(LogType.CLUSTER, `Request ${request_id} was already tracked — rejected the prior promise`);
132			}
133	
134			if (this.pendingRequests.size >= this.maxPending) {
135				this.droppedForCapacity++;
136				logger.warn(
137					LogType.CLUSTER,
138					`Request ${request_id} rejected: tracker at capacity (${this.maxPending} pending)`
139				);
140				return Promise.reject(
141					new Error(`Request ${request_id} rejected: RequestTracker at capacity (${this.maxPending} pending)`)
142				);
143			}
144	
145			return new Promise<MessageResponseIPC>((resolve, reject) => {
146				const timeout = setTimeout(() => {
147					this.pendingRequests.delete(request_id);
148					this.onSettle?.(request_id);
149					reject(new Error(`Request ${request_id} timed out after ${timeoutMs || this.defaultTimeout}ms`));
150				}, timeoutMs || this.defaultTimeout);
151	
152				this.pendingRequests.set(request_id, {
153					resolve,
154					reject,
155					timeout,
156					timestamp: Date.now()
157				});
158	
159				logger.info(
160					LogType.CLUSTER,
161					`Tracking request ${request_id} with timeout ${timeoutMs || this.defaultTimeout}ms`
162				);
163			});
164		}
165	
166		/**
167		 * Resolve a tracked request with a response
168		 */
169		resolveRequest(request_id: string, response: MessageResponseIPC): boolean {
170			const pending = this.pendingRequests.get(request_id);
171			if (!pending) {
172				// Audit 1.6: a success response arriving AFTER the tracker
173				// timed out used to be dropped silently. We now keep a
174				// bounded ring of late successes and fire the onLateSuccess
175				// hook so the caller can convert the timeout into OK. A
176				// failure response is still discarded — letting late
177				// failures slip through would let a real defer failure
178				// masquerade as a late success.
179				if (response?.success) {
180					this.recordLateSuccess(request_id, response);
181					logger.warn(LogType.CLUSTER, `[late_success] received success for already-settled request ${request_id}`);
182					this.onLateSuccess?.(request_id, response);
183				} else {
184					logger.warn(LogType.CLUSTER, `Received response for unknown request ${request_id}`);
185				}
186				return false;
187			}
188	
189			clearTimeout(pending.timeout);
190			this.pendingRequests.delete(request_id);
191			this.onSettle?.(request_id);
192	
193			const duration = Date.now() - pending.timestamp;
194			logger.info(LogType.CLUSTER, `Request ${request_id} resolved in ${duration}ms`);
195	
196			pending.resolve(response);
197			return true;
198		}
199	
200		/**
201		 * Audit 1.6: bounded ring of late-arriving success responses. The
202		 * oldest entry is evicted FIFO when the cap is hit so a sustained
203		 * stream of late successes can't grow the Map without bound.
204		 */
205		private recordLateSuccess(request_id: string, response: MessageResponseIPC): void {
206			if (this.lateSuccesses.size >= RequestTracker.LATE_SUCCESS_MAX) {
207				const oldest = this.lateSuccesses.keys().next().value;
208				if (oldest !== undefined) this.lateSuccesses.delete(oldest);
209			}
210			this.lateSuccesses.set(request_id, response);
211		}
212	
213		/**
214		 * Audit 1.6: lookup (and clear) a late success. The InteractionGrpcService
215		 * calls this from its catch block after a tracker-timeout to check
216		 * whether the worker actually completed the defer despite the timer.
217		 */
218		consumeLateSuccess(request_id: string): MessageResponseIPC | null {
219			const response = this.lateSuccesses.get(request_id);
220			if (response) this.lateSuccesses.delete(request_id);
221			return response ?? null;
222		}
223	
224		/**
225		 * Reject a tracked request with an error
226		 */
227		rejectRequest(request_id: string, error: Error): boolean {
228			const pending = this.pendingRequests.get(request_id);
229			if (!pending) {
230				logger.warn(LogType.CLUSTER, `Cannot reject unknown request ${request_id}`);
231				return false;
232			}
233	
234			clearTimeout(pending.timeout);
235			this.pendingRequests.delete(request_id);
236			this.onSettle?.(request_id);
237	
238			logger.error(LogType.CLUSTER, `Request ${request_id} rejected:`, error);
239	
240			pending.reject(error);
241			return true;
242		}
243	
244		/**
245		 * Get the number of pending requests
246		 */
247		getPendingCount(): number {
248			return this.pendingRequests.size;
249		}
250	
251		/**
252		 * Peticiones rechazadas de entrada desde el arranque por estar el tracker
253		 * a tope (`maxPending`). Distinto de un timeout: aquí la petición ni
254		 * siquiera llega a intentarse contra el worker.
255		 */
256		getDroppedForCapacity(): number {
257			return this.droppedForCapacity;
258		}
259	
260		/**
261		 * Clear all pending requests (useful for testing or shutdown)
262		 */
263		clearAll(): void {
264			for (const pending of this.pendingRequests.values()) {
265				clearTimeout(pending.timeout);
266				pending.reject(new Error("Request tracker cleared"));
267			}
268			this.pendingRequests.clear();
269			this.lateSuccesses.clear();
270			logger.info(LogType.CLUSTER, "All pending requests cleared");
271		}
272	}
